Object value = propertySource.getProperty(key);
if (value != null) {
	if (resolveNestedPlaceholders) {
		if (value instanceof String string) {
			value = resolveNestedPlaceholders(string);
		}
		else if ((value instanceof CharSequence cs) && (String.class.equals(targetValueType) ||
				CharSequence.class.equals(targetValueType))) {
			value = resolveNestedPlaceholders(cs.toString());
		}
	}
	logKeyFound(key, propertySource, value);
	return convertValueIfNecessary(value, targetValueType);
}

@Override
public @Nullable String getProperty(String key) {
	return getProperty(key, String.class, true);
}

@Override
public <T> @Nullable T getProperty(String key, Class<T> targetValueType) {
	return getProperty(key, targetValueType, true);
}

@Override
protected @Nullable String getPropertyAsRawString(String key) {
	return getProperty(key, String.class, false);
}

/**
 * Resolve placeholders within the given string, deferring to the value of
 * {@link #setIgnoreUnresolvableNestedPlaceholders} to determine whether any
 * unresolvable placeholders should raise an exception or be ignored.
 * <p>Invoked from {@link #getProperty} and its variants, implicitly resolving
 * nested placeholders. In contrast, {@link #resolvePlaceholders} and
 * {@link #resolveRequiredPlaceholders} do <i>not</i> delegate
 * to this method but rather perform their own handling of unresolvable
 * placeholders, as specified by each of those methods.
 * @since 3.2
 * @see #setIgnoreUnresolvableNestedPlaceholders
 */
protected String resolveNestedPlaceholders(String value) {
	if (value.isEmpty()) {
		return value;
	}
	return (this.ignoreUnresolvableNestedPlaceholders ?
			resolvePlaceholders(value) : resolveRequiredPlaceholders(value));
}

@Override
public ConfigurableConversionService getConversionService() {
	// Need to provide an independent DefaultConversionService, not the
	// shared DefaultConversionService used by PropertySourcesPropertyResolver.
	ConfigurableConversionService cs = this.conversionService;
	if (cs == null) {
		synchronized (this) {
			cs = this.conversionService;
			if (cs == null) {
				cs = new DefaultConversionService();
				this.conversionService = cs;
			}
		}
	}
	return cs;
}

@Override
public void setConversionService(ConfigurableConversionService conversionService) {
	Assert.notNull(conversionService, "ConversionService must not be null");
	this.conversionService = conversionService;
}

public String getProperty(String key, String defaultValue) {
	String value = getProperty(key);
	return (value != null ? value : defaultValue);
}

@Override
public <T> T getProperty(String key, Class<T> targetType, T defaultValue) {
	T value = getProperty(key, targetType);
	return (value != null ? value : defaultValue);
}

@Override
public String getRequiredProperty(String key) throws IllegalStateException {
	String value = getProperty(key);
	if (value == null) {
		throw new IllegalStateException("Required key '" + key + "' not found");
	}
	return value;
}

@Override
public <T> T getRequiredProperty(String key, Class<T> valueType) throws IllegalStateException {
	T value = getProperty(key, valueType);
	if (value == null) {
		throw new IllegalStateException("Required key '" + key + "' not found");
	}
	return value;
}
